// Consolida o que a execucao removeu, somando TODAS as linhas que o bloco
// anterior devolveu do jurisflow_purga_log. Ler apenas $json pegaria so o
// ultimo bloco de purga: foi assim que, na primeira tentativa, duas linhas
// removidas da trilha nao dispararam alerta nenhum.
const linhas = $input.all().map(function (i) { return i.json; })
  .filter(function (r) { return r && r.linhas_removidas !== undefined; });

let total = 0;
const detalhe = [];
for (const r of linhas) {
  const n = Number(r.linhas_removidas) || 0;
  total += n;
  detalhe.push('• ' + r.alvo + ' (' + r.prazo + '): ' + n + ' removida(s)');
}

const falhou = linhas.length === 0;

// Um relatorio que chega todo dia dizendo "zero removido" deixa de ser lido em
// duas semanas, e alerta que ninguem le e pior do que alerta nenhum. So
// notifica quando houve remocao ou quando a purga nao retornou contagem.
const deveNotificar = falhou || total > 0;

return [{
  json: {
    executado_em: new Date().toISOString(),
    total_removido: total,
    blocos: linhas.length,
    detalhe: detalhe.join('\n') || 'nenhum bloco retornou contagem',
    falhou: falhou,
    deve_notificar: deveNotificar,
    severidade: falhou ? 'P2' : (total > 0 ? 'P2' : 'informativo'),
  },
}];

